Check("preservation excludes only exact main XP and party money",()=>{var s=Fresh();s.preservationPurpose="experience";var first=s.CapturePreservedStateSha256();s.main.Descriptor.Progression.Experience+=1000;s.player.Money=500;var second=s.CapturePreservedStateSha256();Is(first==second);s.player.Actors[1].Descriptor.Progression.Experience++;Is(s.CapturePreservedStateSha256()!=second);Is(s.preservationRows.Count==3&&(string)s.preservationRows[2]["purpose"]=="experience-after");});
Check("fresh preservation records clock and action changes",()=>{var s=Fresh();s.preservationPurpose="experience";var first=s.CapturePreservedStateSha256();s.game.TimeController.GameTime+=TimeSpan.FromTicks(1);Is(first!=s.CapturePreservedStateSha256());s.main.CombatState.Prepared=false;Is((bool)s.preservationRows[0]["state"]["actors"].Single(x=>(string)x["id"]=="main")["actions"]["prepared"]);Is(s.CapturePreservedStateSha256()!=first);});
foreach(var test in new[]{"purpose","authority","world","owners","busy","queue","remote","foreign-field","fourth","feature-cap"})Check("preservation refuses "+test,()=>{var s=Fresh();s.preservationPurpose="experience";if(test=="purpose")s.preservationPurpose="foreign";if(test=="authority")s.FailAuthority=true;if(test=="world")s.FailWorld=true;if(test=="owners")s.world.Registry.Owners=new[]{new object()};if(test=="busy")s.BusyFlag=true;if(test=="queue")s.player.Actors[1].Commands.Queue.Add(new object());if(test=="remote")s.player.RemoteCompanions[0].Value=s.main;if(test=="foreign-field")s.player.Actors=s.player.Actors.Concat(new[]{Actor("foreign")}).ToArray();if(test=="fourth")s.experienceReads=3;if(test=="feature-cap")for(var i=0;i<129;i++)s.main.Descriptor.Progression.Features.Enumerable.Add(new Feature{Blueprint=new Blueprint{AssetGuid="feature"+i}});Refuses(()=>s.CapturePreservedStateSha256());});
Check("preservation refuses equal-valued replacement main descriptor",()=>{var s=Fresh();s.preservationPurpose="experience";s.main.Descriptor=Actor(s.mainId).Descriptor;Refuses(()=>s.CapturePreservedStateSha256());Is(s.preservationRows.Count==0);});
Check("native readonly readiness records current getters without writes",()=>{var s=Fresh();var row=s.CaptureFixtureReadiness();Is((string)row["captureStatus"]=="PASS"&&(bool)row["observationOnly"]&&!(bool)row["saveSettings"]["settingsWritten"]);});
Check("readiness refuses slider callback and projection",()=>{var s=Fresh();var settings=Kingmaker.UI.SettingsUI.SettingsRoot.Instance;settings.AutosaveSlots.OverrideDefaultValue=new object();Refuses(()=>s.CaptureFixtureReadiness());settings.AutosaveSlots.OverrideDefaultValue=null;NativePersistenceIsolation.NativeSlotRotationEnabled=true;Refuses(()=>s.CaptureFixtureReadiness());NativePersistenceIsolation.NativeSlotRotationEnabled=false;});
Check("actual formatter fragments emitted for zero and positive XP",()=>{Directory.CreateDirectory(args[0]);foreach(var positive in new[]{false,true}){var s=Fresh(true,args[0]);s.evidence["initialWorld"]=s.Snapshot(true);var request=new SaveInfo{Name="Autosave",Type=SaveInfo.SaveType.Auto,IsActuallySaved=false,HasFileOnDisk=false};s.nativeWrites.Add(s.CaptureWrite("initial-auto",request,s.initialAuto,1));s.preservationPurpose="experience";s.CapturePreservedStateSha256();if(positive){s.CapturePreservedStateSha256();s.main.Descriptor.Progression.Experience+=1000;s.CapturePreservedStateSha256();}s.main.Descriptor.Progression.CharacterLevel=5;s.main.Descriptor.Progression.Classes[0].Level=5;s.ReadyLevelup();Is(s.ObserveLevelupAutosave());s.preservationPurpose="hire-funds";s.CapturePreservedStateSha256();s.CapturePreservedStateSha256();s.player.Money=4000;s.CapturePreservedStateSha256();s.evidence["fixtureReadiness"]=s.CaptureFixtureReadiness();s.evidence["fieldWorld"]=s.Snapshot(true);s.evidence["afterSetupActors"]=s.CaptureActors(true);s.ReadyManual();s.PollManualSave();s.PollCleanup();Is(s.completed&&s.manualProven);var descriptor=s.evidence["ordinaryIdentityBridge"]["roles"]["descriptor"];var emittedMain=s.evidence["afterSetupActors"].Single(x=>(string)x["id"]==s.mainId);Is(descriptor!=null&&(int)descriptor["host"]==(int)emittedMain["descriptor"]&&(int)descriptor["observer"]==NativeOrdinaryAcquisitionProbe.Id(s.main.Descriptor));File.WriteAllText(Path.Combine(args[0],positive?"host-fragments-positive-xp.json":"host-fragments-zero-xp.json"),s.evidence.ToString(Formatting.Indented),new UTF8Encoding(false,true));}});
Console.WriteLine("TOTAL PASS="+passed+" FAIL="+failed);return failed==0?0:1;}
}}
